WITH session_stats AS (SELECT session_id, AVG(duration_sec) avg_duration_sec, MAX(duration_sec) max_duration_sec FROM web_events WHERE duration_sec > 412 GROUP BY session_id) SELECT sessions.id, sessions.started_at, sessions.customer_id, session_stats.avg_duration_sec, session_stats.max_duration_sec FROM sessions INNER JOIN session_stats ON sessions.id = session_stats.session_id WHERE session_stats.max_duration_sec > 220 ORDER BY customer_id;
